c0=A.aw(s2,A.a([A.av(A.a(["\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \ub300\uc751 \uac1c\ub150 \ud559\uc2b5"],ai0),B.D,A.a([A.ax(s3,B.u,A.a(["\ub450 \uc9d1\ud569 $X$\uc640 $Y$\uac00 \uc788\uc744 \ub54c, \uc9d1\ud569 $X$\uc758 \uac01 \uc6d0\uc18c\uc5d0 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c\ub97c \uc9dd\uc9c0\uc5b4 \uc8fc\ub294 \uac83\uc744 '\ub300\uc751'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc6b0\ub9ac \ubc18 \ud559\uc0dd\ub4e4\uc758 \uc774\ub984\uc774 \uc801\ud78c \uc9d1\ud569 $X$\uc640 \uadf8\ub4e4\uc758 \ud608\uc561\ud615\uc774 \uc801\ud78c \uc9d1\ud569 $Y$\uac00 \uc788\ub2e4\uba74, \uac01 \ud559\uc0dd\uc5d0\uac8c \ud574\ub2f9\ud558\ub294 \ud608\uc561\ud615\uc744 \uc5f0\uacb0\ud558\ub294 \uac83\uc774 \ubc14\ub85c \ub300\uc751\uc785\ub2c8\ub2e4. \uc774\ub54c \uc9d1\ud569 $X$\ub97c \ub300\uc751\uc758 \uc2dc\uc791\uc810\uc778 '\uc815\uc758\uc5ed'\uacfc \uad00\ub828\ub41c \uc9d1\ud569\uc73c\ub85c, \uc9d1\ud569 $Y$\ub97c \ub300\uc751\uc758 \ub3c4\ucc29\uc810\uc778 '\uacf5\uc5ed'\uacfc \uad00\ub828\ub41c \uc9d1\ud569\uc73c\ub85c \uc0dd\uac01\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub300\uc751\uc740 \ud654\uc0b4\ud45c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc2dc\uac01\uc801\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc9d1\ud569 $X$\uc758 \uc6d0\uc18c $x$\uc5d0\uc11c \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c $y$\ub85c \ud654\uc0b4\ud45c\ub97c \uadf8\uc5b4 $x$\uac00 $y$\uc5d0 \ub300\uc751\ub428\uc744 \ud45c\ud604\ud558\uba70, \uc774\ub97c \uae30\ud638\ub85c $x \\longmapsto y$\uc640 \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ub300\uc751\uc740 \ub2e8\uc21c\ud788 \uc9dd\uc744 \uc9d3\ub294 \ubaa8\ub4e0 \uad00\uacc4\ub97c \ud3ec\ud568\ud558\ub294 \ub113\uc740 \uac1c\ub150\uc73c\ub85c, \ub098\uc911\uc5d0 \ubc30\uc6b0\uac8c \ub420 '\ud568\uc218'\ub294 \uc774 \ub300\uc751 \uc911\uc5d0\uc11c '\uc9d1\ud569 $X$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c\uc5d0 \uc624\uc9c1 \ud558\ub098\uc529\ub9cc \ub300\uc751\ub418\ub294 \ud2b9\ubcc4\ud55c \uaddc\uce59'\uc744 \uac00\uc9c4 \uac83\uc744 \ub9d0\ud569\ub2c8\ub2e4.","\ub300\uc751\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uae30 \uc704\ud574 \uc9d1\ud569 $X = \\{1, 2, 3\\}$\uacfc $Y = \\{a, b, c, d\\}$\ub97c \uc608\ub85c \ub4e4\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. $1$\uc740 $a$\uc5d0, $2$\ub294 $b$\uc5d0, $3$\uc740 $c$\uc5d0 \ub300\uc751\uc2dc\ud0a4\ub294 \uac83\uacfc \uac19\uc774, \uc9d1\ud569 $X$\uc758 \uc6d0\uc18c\ub4e4\uc774 \uc9d1\ud569 $Y$\uc758 \uc6d0\uc18c \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud558\uc5ec \uc5f0\uacb0\ub418\ub294 \ubaa8\ub4e0 \uacbd\uc6b0\uc758 \uc218\uac00 \ub300\uc751\uc758 \uc608\uc2dc\uac00 \ub429\ub2c8\ub2e4. \ub300\uc751\uc5d0\uc11c\ub294 $X$\uc758 \ud55c \uc6d0\uc18c\uac00 $Y$\uc758 \uc5ec\ub7ec \uc6d0\uc18c\uc5d0 \ub300\uc751\ub420 \uc218\ub3c4 \uc788\uace0, $X$\uc758 \uc5b4\ub5a4 \uc6d0\uc18c\ub294 $Y$\uc758 \uc544\ubb34 \uc6d0\uc18c\uc640\ub3c4 \ub300\uc751\ub418\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \ub450 \uc9d1\ud569 $X = \\{1, 2\\}$, $Y = \\{3, 4, 5\\}$\uac00 \uc788\uc744 \ub54c, \uc9d1\ud569 $X$\uc5d0\uc11c \uc9d1\ud569 $Y$\ub85c\uc758 \ub300\uc751 \uad00\uacc4\ub97c \ud558\ub098 \uc815\ud574\ubd05\uc2dc\ub2e4. '\uc9d1\ud569 $X$\uc758 \uc6d0\uc18c $x$\uc5d0 $x+2$\ub97c \ub354\ud55c \uac12\uc744 \ub300\uc751\uc2dc\ud0a8\ub2e4'\ub294 \uaddc\uce59\uc744 \uc801\uc6a9\ud558\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c\uc694? \uba3c\uc800 $x=1$\uc77c \ub54c, $1+2=3$\uc774\ubbc0\ub85c $1$\uc740 $3$\uc5d0 \ub300\uc751\ub429\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c $x=2$\uc77c \ub54c, $2+2=4$\uc774\ubbc0\ub85c $2$\ub294 $4$\uc5d0 \ub300\uc751\ub429\ub2c8\ub2e4.","\uc704\uc758 \ub300\uc751\uc744 \uae30\ud638\ub85c \uc815\ub9ac\ud558\uba74 $1 \\longmapsto 3$ \uadf8\ub9ac\uace0 $2 \\longmapsto 4$\uac00 \ub429\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc744 \uc9d1\ud569\uc758 \uc6d0\uc18c\ub85c \ud45c\ud604\ud558\uba74 \ub300\uc751 \uad00\uacc4\ub294 $\\{(1, 3), (2, 4)\\}$\uc640 \uac19\uc774 \uc21c\uc11c\uc30d\uc758 \uc9d1\ud569\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc11c $5$\ub294 \uc9d1\ud569 $X$\uc758 \uc5b4\ub5a4 \uc6d0\uc18c\uc640\ub3c4 \ub300\uc751\ub418\uc9c0 \uc54a\uc558\ub294\ub370, \ub300\uc751\uc758 \uc815\uc758\uc5d0\uc11c\ub294 \uc9d1\ud569 $Y$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 \ubc18\ub4dc\uc2dc \uc120\ud0dd\ubc1b\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\uc73c\ubbc0\ub85c \uc774 \ub610\ud55c \uc62c\ubc14\ub978 \ub300\uc751\uc758 \uc0ac\ub840\uac00 \ub429\ub2c8\ub2e4."],ai0),"\ub300\uc751",B.q)],ai2),"\ub300\uc751",B.q)],ai3),s3,s3,s3,"concept_\ub300\uc751",0,"","\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \ub300\uc751",c0,"\ub300\uc751",s3)
c1=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ud55c","\uadf9\ud55c\uc758\uc815\uc758","\uc6b0\uadf9\ud55c"],ai0)
c1=A.aw(s2,A.a([A.av(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc6b0\uadf9\ud55c \uac1c\ub150 \ud559\uc2b5"],ai0),B.D,A.a([A.ax(s3,B.u,A.a(['[   "\ud568\uc218\uc758 \uadf9\ud55c\uc5d0\uc11c \'\uc6b0\uadf9\ud55c\'\uc774\ub780, \ubcc0\uc218 $x$\uac00 \uc5b4\ub5a4 \uac12 $a$\ubcf4\ub2e4 \ud070 \ucabd\uc5d0\uc11c $a$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c8 \ub54c, \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \uc77c\uc815\ud55c \uac12 $L$\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \uc0c1\ud0dc\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc989, \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c $a$\uc758 \uc624\ub978\ucabd \ubc29\ud5a5\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \ub2e4\uac00\uac00\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud558\uba70, \uc774\ub97c \uae30\ud638\ub85c\ub294 $x \\\\to a+$\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4. \uc774\ub54c\uc758 \uadf9\ud55c\uac12\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to a+} f(x) = L $$",   "\uc6b0\uadf9\ud55c\uc744 \uc774\ud574\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uc810\uc740 $x$\uac00 $a$\ubcf4\ub2e4 \ud070 \uac12\uc744 \uac00\uc9c0\uba74\uc11c $a$\ub85c \uc811\uadfc\ud55c\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ud568\uc218\uac00 $x=a$\uc5d0\uc11c \ub04a\uc5b4\uc838 \uc788\uac70\ub098, $x=a$\uc5d0\uc11c\uc758 \ud568\uc22b\uac12\uacfc \uc0c1\uad00\uc5c6\uc774 \uc624\ub978\ucabd\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \uadf8\ub798\ud504\uc758 \ub192\uc774\ub9cc \uad00\ucc30\ud558\uba74 \ub429\ub2c8\ub2e4. \ub9cc\uc57d $x$\uac00 $a$\uc5d0 \uac00\uae4c\uc6cc\uc9c8 \ub54c \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \ubb34\ud55c\ud788 \ucee4\uc9c0\uac70\ub098 \uc791\uc544\uc9c0\uc9c0 \uc54a\uace0 \ud2b9\uc815\ud55c \uc2e4\uc218 $L$\uc5d0 \uc218\ub834\ud55c\ub2e4\uba74, \uc6b0\ub9ac\ub294 \uadf8 $L$\uc744 \uc6b0\uadf9\ud55c\uac12\uc774\ub77c\uace0 \uc815\uc758\ud569\ub2c8\ub2e4.",   "\uc6b0\uadf9\ud55c\uc758 \uc131\uc9c8\uc740 \uc77c\ubc18\uc801\uc778 \uadf9\ud55c\uc758 \uc131\uc9c8\uacfc \ub3d9\uc77c\ud569\ub2c8\ub2e4. \ub450 \ud568\uc218 $f(x)$\uc640 $g(x)$\uc5d0 \ub300\ud558\uc5ec \uc6b0\uadf9\ud55c\uc774 \uac01\uac01 \uc874\uc7ac\ud560 \ub54c, \uc0c1\uc218\ubc30, \ub367\uc148, \ube84\uc148, \uacf1\uc148, \ub098\ub217\uc148(\ub2e8, \ubd84\ubaa8\uc758 \uc6b0\uadf9\ud55c\uc774 0\uc774 \uc544\ub2d0 \ub54c)\uc5d0 \ub300\ud558\uc5ec \uac01\uac01\uc758 \uc6b0\uadf9\ud55c\uc744 \ub530\ub85c \uacc4\uc0b0\ud558\uc5ec \uc5f0\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ub450 \ud568\uc218\uc758 \ud569\uc758 \uc6b0\uadf9\ud55c\uc740 \uac01 \ud568\uc218\uc758 \uc6b0\uadf9\ud55c\uc758 \ud569\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to a+} \\{f(x) + g(x)\\} = \\\\lim_{x\\\\to a+} f(x) + \\\\lim_{x\\\\to a+} g(x) $$",   "\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud568\uc218 $f(x) = \\\\begin{cases} x+2 & (x \\\\ge 1) \\\\\\\\ 3x & (x < 1) \\\\end{cases}$\uc77c \ub54c, $x \\\\to 1+$\uc5d0\uc11c\uc758 \uc6b0\uadf9\ud55c\uc744 \uad6c\ud574\ubcf4\uc138\uc694. \uc6b0\uadf9\ud55c\uc740 $x$\uac00 1\ubcf4\ub2e4 \ud070 \ucabd\uc5d0\uc11c 1\ub85c \ub2e4\uac00\uac00\ub294 \uac83\uc774\ubbc0\ub85c, $x > 1$\uc77c \ub54c\uc758 \uc2dd\uc778 $f(x) = x+2$\ub97c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $x > 1$\uc778 \uad6c\uac04\uc758 \ud568\uc218\uc2dd\uc744 \ud655\uc778\ud569\ub2c8\ub2e4. \ub458\uc9f8, \ud574\ub2f9 \uc2dd\uc5d0 $x=1$\uc744 \ub300\uc785\ud558\uc5ec \uadf9\ud55c\uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to 1+} f(x) = \\\\lim_{x \\\\to 1+} (x+2) = 1+2 = 3 $$",   "\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, \ubd84\uc218 \ud568\uc218 $f(x) = \\\\frac{|x-2|}{x-2}$\uc758 $x \\\\to 2+$\uc5d0\uc11c\uc758 \uc6b0\uadf9\ud55c\uc744 \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc774 \ud568\uc218\ub294 $x$\uac00 2\ubcf4\ub2e4 \ud074 \ub54c\uc640 \uc791\uc744 \ub54c\uc758 \ud615\ud0dc\uac00 \ub2e4\ub985\ub2c8\ub2e4. $x > 2$\uc774\uba74 $x-2 > 0$\uc774\ubbc0\ub85c $|x-2| = x-2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $f(x) = \\\\frac{x-2}{x-2} = 1$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uadf9\ud55c\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\\\lim_{x \\\\to 2+} \\\\frac{|x-2|}{x-2} = \\\\lim_{x \\\\to 2+} 1 = 1 $$ \uc774\ucc98\ub7fc \uc6b0\uadf9\ud55c\uc740 \uadf8\ub798\ud504\uc758 \uc624\ub978\ucabd\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \uacbd\ub85c\ub97c \ub530\ub77c \ud568\uc218\uac00 \ud5a5\ud558\ub294 \ubaa9\uc801\uc9c0\ub97c \ucc3e\ub294 \uacfc\uc815\uc784\uc744 \uae30\uc5b5\ud558\uba74 \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4." ]'],ai0),"\uc6b0\uadf9\ud55c",B.q)],ai2),"\uc6b0\uadf9\ud55c",B.q)],ai3),s3,s3,s3,"concept_\uc6b0\uadf9\ud55c",0,"","\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc815\uc758 > \uc6b0\uadf9\ud55c",c1,"\uc6b0\uadf9\ud55c",s3)
c2=A.a(["\uacf5\ud1b5\uc218\ud5591","\ubcf5\uc18c\uc218","\ucf24\ub808\ubcf5\uc18c\uc218"],ai0)
c2=A.aw(s2,A.a([A.av(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ucf24\ub808\ubcf5\uc18c\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.D,A.a([A.ax(s3,B.u,A.a(["\ubcf5\uc18c\uc218 $z = a + bi$ (\ub2e8, $a, b$\ub294 \uc2e4\uc218)\uc5d0 \ub300\ud558\uc5ec, \ud5c8\uc218\ubd80\ubd84\uc758 \ubd80\ud638\ub97c \ubc14\uafbc $a - bi$\ub97c $z$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub77c\uace0 \ud558\uba70, \uae30\ud638\ub85c\ub294 $\\bar{z}$\uc640 \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ubcf5\uc18c\uc218 $3 + 2i$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub294 $3 - 2i$\uc774\uace0, $-1 - 5i$\uc758 \ucf24\ub808\ubcf5\uc18c\uc218\ub294 $-1 + 5i$\uc785\ub2c8\ub2e4. \uc2e4\uc218 \ubd80\ubd84\uc740 \uadf8\ub300\ub85c \ub450\uace0 \ud5c8\uc218 \ubd80\ubd84\uc758 \ubd80\ud638\ub9cc \ubc18\ub300\ub85c \ubc14\uafbc\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uc138\uc694.","\ucf24\ub808\ubcf5\uc18c\uc218\ub294 \uc0ac\uce59\uc5f0\uc0b0\uacfc \uad00\ub828\ud558\uc5ec \ub9e4\uc6b0 \uc720\uc6a9\ud55c \uc131\uc9c8\ub4e4\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \ubcf5\uc18c\uc218 $z_1, z_2$\uc5d0 \ub300\ud558\uc5ec $\\overline{z_1 + z_2} = \\bar{z_1} + \\bar{z_2}$, $\\overline{z_1 - z_2} = \\bar{z_1} - \\bar{z_2}$, $\\overline{z_1 z_2} = \\bar{z_1} \\cdot \\bar{z_2}$, $\\overline{\\left(\\frac{z_1}{z_2}\\right)} = \\frac{\\bar{z_1}}{\\bar{z_2}}$ ($z_2 \\neq 0$)\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub610\ud55c, \uc5b4\ub5a4 \ubcf5\uc18c\uc218\uc640 \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \ub354\ud558\uac70\ub098 \uacf1\ud558\uba74 \ud56d\uc0c1 \uc2e4\uc218\uac00 \ub41c\ub2e4\ub294 \uc911\uc694\ud55c \ud2b9\uc9d5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $z + \\bar{z} = 2a$\uc774\uace0 $z \\cdot \\bar{z} = a^2 + b^2$\uc785\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \ubb38\uc81c: \ubcf5\uc18c\uc218 $z = 2 + i$\uc77c \ub54c, $z \\cdot \\bar{z}$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 $z = 2 + i$\uc774\ubbc0\ub85c, \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218 $\\bar{z}$\ub294 \ud5c8\uc218 \ubd80\ubd84\uc758 \ubd80\ud638\ub97c \ubc14\uafbc $2 - i$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \ub450 \uc218\ub97c \uacf1\ud558\ub294 \uacfc\uc815\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc218\ud589\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uacf1\uc148 \uc2dd\uc744 \uc138\uc6b0\uba74 $z \\cdot \\bar{z} = (2 + i)(2 - i)$\uc785\ub2c8\ub2e4. \uc774\ub97c \uc804\uac1c\ud558\uba74 $(2)^2 - (i)^2$\uc774 \ub418\ub294\ub370, \ubcf5\uc18c\uc218\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $i^2 = -1$\uc784\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $4 - (-1) = 4 + 1 = 5$\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ubcf5\uc18c\uc218\uc640 \uadf8 \ucf24\ub808\ubcf5\uc18c\uc218\ub97c \uacf1\ud558\uba74 \ud56d\uc0c1 \ud5c8\uc218 \ub2e8\uc704 $i$\uac00 \uc0ac\ub77c\uc9c0\uace0 \uc2e4\uc218\uac00 \ub41c\ub2e4\ub294 \uc810\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v5,B.q)],ai2),v5,B.q)],ai3),s3,s3,s3,"concept_\ucf24\ub808\ubcf5\uc18c\uc218",0,"","\uacf5\ud1b5\uc218\ud5591 > \ubcf5\uc18c\uc218 > \ucf24\ub808\ubcf5\uc18c\uc218",c2,v5,s3)
c3=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc6d0\uc758\ubc29\uc815\uc2dd","\uc6d0\uc758\ud45c\uc900\ud615","\uc911\uc2ec"],ai0)
c3=A.aw(s2,A.a([A.av(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \uc911\uc2ec \uac1c\ub150 \ud559\uc2b5"],ai0),B.D,A.a([A.ax(s3,B.u,A.a(["\uc6d0\uc758 \uc911\uc2ec\uc774\ub780 \uc6d0\uc744 \uad6c\uc131\ud558\ub294 \ubaa8\ub4e0 \uc810\uc73c\ub85c\ubd80\ud130 \uac19\uc740 \uac70\ub9ac\uc5d0 \uc788\ub294 \ud3c9\uba74 \uc704\uc758 \uace0\uc815\ub41c \uc810\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc6d0\uc758 \ubc29\uc815\uc2dd\uc5d0\uc11c \uc911\uc2ec\uc740 \uc6d0\uc758 \uc704\uce58\ub97c \uacb0\uc815\ud558\ub294 \uac00\uc7a5 \uc911\uc694\ud55c \uc694\uc18c\uc774\uba70, \uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \uc6d0\uc758 \uc911\uc2ec\uc744 $(a, b)$\ub77c\uace0 \ud560 \ub54c, \uc911\uc2ec\uc73c\ub85c\ubd80\ud130\uc758 \uac70\ub9ac\uac00 \ubc18\uc9c0\ub984 $r$\uc778 \uc6d0\uc758 \ubc29\uc815\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \ud45c\uc900\ud615\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$ (x - a)^2 + (y - b)^2 = r^2 $$ \uc774 \uc2dd\uc5d0\uc11c $x$\uc640 $y$\uc758 \uac12\uc5d0 \uac01\uac01 $a$\uc640 $b$\ub97c \ub300\uc785\ud558\uba74 \uc88c\ubcc0\uc774 $0$\uc774 \ub418\uc5b4 \ubc18\uc9c0\ub984\uc758 \uc81c\uacf1\uc778 $r^2$\uacfc \uac19\uc544\uc9c0\ubbc0\ub85c, \uc810 $(a, b)$\uac00 \uc6d0\uc758 \uc911\uc2ec\uc784\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc6d0\uc758 \ubc29\uc815\uc2dd\uc774 \uc77c\ubc18\ud615\uc778 $x^2 + y^2 + Ax + By + C = 0$\uc758 \ud615\ud0dc\ub85c \uc8fc\uc5b4\uc9c8 \ub54c\ub294, \uc644\uc804\uc81c\uacf1\uc2dd\uc744 \uc774\uc6a9\ud558\uc5ec \ud45c\uc900\ud615\uc73c\ub85c \ubcc0\ud615\ud574\uc57c \uc911\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $x$\ud56d\ub07c\ub9ac, $y$\ud56d\ub07c\ub9ac \ubb36\uc5b4 \uc815\ub9ac\ud558\uba74 $x^2 + Ax + (\frac{A}{2})^2$\uc640 $y^2 + By + (\frac{B}{2})^2$\uc758 \uaf34\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc73c\uba70, \uc774\ub97c \ud1b5\ud574 \uc911\uc2ec\uc758 \uc88c\ud45c $(a, b)$\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$ a = -\frac{A}{2}, \\; b = -\frac{B}{2} $$ \uc989, \uc77c\ubc18\ud615\uc5d0\uc11c \uc911\uc2ec\uc758 \uc88c\ud45c\ub294 $x$\uc640 $y$\uc758 \uc77c\ucc28\ud56d \uacc4\uc218\ub97c \uac01\uac01 $-2$\ub85c \ub098\ub208 \uac12\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc911\uc2ec\uc744 \ucc3e\uc544\ubd05\uc2dc\ub2e4. \ubc29\uc815\uc2dd $(x - 3)^2 + (y + 2)^2 = 16$\uc774 \ub098\ud0c0\ub0b4\ub294 \uc6d0\uc758 \uc911\uc2ec\uc744 \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc774 \uc2dd\uc740 \uc774\ubbf8 \ud45c\uc900\ud615\uc73c\ub85c \uc798 \uc815\ub9ac\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ud45c\uc900\ud615\uc758 \uae30\ubcf8 \ud615\ud0dc\uc778 $(x - a)^2 + (y - b)^2 = r^2$\uacfc \ube44\uad50\ud574 \ubcf4\uba74, $a = 3$\uc774\uace0 $b = -2$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \uc6d0\uc758 \uc911\uc2ec\uc740 $(3, -2)$\uac00 \ub429\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c \uc77c\ubc18\ud615 \ubc29\uc815\uc2dd $x^2 + y^2 - 4x + 6y - 3 = 0$\uc758 \uc911\uc2ec\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$\ud56d\uacfc $y$\ud56d\uc744 \ubaa8\uc544 \uc644\uc804\uc81c\uacf1\uc2dd\uc73c\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. $(x^2 - 4x) + (y^2 + 6y) = 3$\uc5d0\uc11c, \uac01 \uad04\ud638 \uc548\uc5d0 \ud544\uc694\ud55c \uc0c1\uc218\ub97c \ub354\ud574\uc90d\ub2c8\ub2e4. $x^2 - 4x + 4$\uc640 $y^2 + 6y + 9$\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc591\ubcc0\uc5d0 $4$\uc640 $9$\ub97c \ub354\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ (x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9 $$ \uc774\ub97c \uc815\ub9ac\ud558\uba74 $(x - 2)^2 + (y + 3)^2 = 16$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \uc6d0\uc758 \uc911\uc2ec\uc740 $(2, -3)$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uc911\uc2ec",B.q)],ai2),"\uc911\uc2ec",B.q)],ai3),s3,s3,s3,"concept_\uc911\uc2ec",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \uc911\uc2ec",c3,"\uc911\uc2ec",s3)
c4=A.a(["\ub300\uc218","\ub85c\uadf8\ud568\uc218","\ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504"],ai0)
c4=A.aw(s2,A.a([A.av(A.a(["\ub300\uc218 > \ub85c\uadf8\ud568\uc218 > \ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504 \uac1c\ub150 \ud559\uc2b5"],ai0),B.D,A.a([A.ax(s3,B.u,A.a(["\ub85c\uadf8\ud568\uc218 $y = \\log_a x$ (\ub2e8, $a > 0, a \\neq 1$)\ub294 \uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \uc5ed\ud568\uc218\uc785\ub2c8\ub2e4. \uc774 \ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub9ac\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc815\uc758\uc5ed\uacfc \uce58\uc5ed\uc744 \uc774\ud574\ud574\uc57c \ud569\ub2c8\ub2e4. \ub85c\uadf8\uc758 \uc815\uc758\uc5d0 \uc758\ud574 \uc9c4\uc218 \uc870\uac74\uc778 $x > 0$\uc774 \ud56d\uc0c1 \uc131\ub9bd\ud574\uc57c \ud558\ubbc0\ub85c, \ub85c\uadf8\ud568\uc218\uc758 \uc815\uc758\uc5ed\uc740 \uc591\uc758 \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc774\uba70, \uce58\uc5ed\uc740 \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uadf8\ub798\ud504\ub294 \ud56d\uc0c1 \uc810 $(1, 0)$\uc744 \uc9c0\ub098\uba70, $y$\ucd95\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4.","\ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504 \ubaa8\uc591\uc740 \ubc11 $a$\uc758 \uac12\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. $a > 1$\uc77c \ub54c, $x$\uac12\uc774 \uc99d\uac00\ud558\uba74 $y$\uac12\ub3c4 \uc99d\uac00\ud558\ub294 \uc99d\uac00\ud568\uc218\uc758 \ud615\ud0dc\ub97c \ub760\uba70 \uadf8\ub798\ud504\ub294 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud569\ub2c8\ub2e4. \ubc18\uba74, $0 < a < 1$\uc77c \ub54c, $x$\uac12\uc774 \uc99d\uac00\ud558\uba74 $y$\uac12\uc740 \uac10\uc18c\ud558\ub294 \uac10\uc18c\ud568\uc218\uc758 \ud615\ud0dc\ub97c \ub760\uba70 \uadf8\ub798\ud504\ub294 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud569\ub2c8\ub2e4. \ub610\ud55c, $y = \\log_a x$\uc640 $y = \\log_{1/a} x$\uc758 \uadf8\ub798\ud504\ub294 $x$\ucd95\uc5d0 \ub300\ud558\uc5ec \uc11c\ub85c \ub300\uce6d\uc778 \uad00\uacc4\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.","\ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \ud3c9\ud589\uc774\ub3d9\ud558\uac70\ub098 \ub300\uce6d\uc774\ub3d9\ud558\uc5ec \ub354\uc6b1 \ub2e4\uc591\ud55c \ud615\ud0dc\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, $y = \\log_a(x - p) + q$\uc758 \uadf8\ub798\ud504\ub294 $y = \\log_a x$\uc758 \uadf8\ub798\ud504\ub97c $x$\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $p$\ub9cc\ud07c, $y$\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc785\ub2c8\ub2e4. \uc774\ub54c \uc810\uadfc\uc120\uc740 \uc6d0\ub798 $x=0$\uc774\uc5c8\uc73c\ub098 \ud3c9\ud589\uc774\ub3d9\uc5d0 \uc758\ud574 $x=p$\ub85c \ubcc0\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ub85c\uadf8\ud568\uc218\uc758 \uadf8\ub798\ud504\ub3c4 \uc27d\uac8c \uadf8\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\uc81c: \ud568\uc218 $y = \\log_2(x - 1) + 3$\uc758 \uadf8\ub798\ud504\uc758 \uc810\uadfc\uc120\uc744 \uad6c\ud558\uace0, $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uccab \ubc88\uc9f8 \ub2e8\uacc4\ub85c \uc810\uadfc\uc120\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\ud568\uc218 $y = \\log_a(x - p) + q$\uc5d0\uc11c \uc9c4\uc218 \uc870\uac74\uc778 $x - p > 0$\uc744 \ub9cc\uc871\ud574\uc57c \ud558\ubbc0\ub85c, $x - 1 > 0$\uc5d0\uc11c $x > 1$\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadf8\ub798\ud504\uc758 \uc810\uadfc\uc120\uc740 $$x = 1$$\uc774 \ub429\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \ub2e8\uacc4\ub85c $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \uc2dd\uc5d0 $x=5$\ub97c \ub300\uc785\ud558\uba74 $$y = \\log_2(5 - 1) + 3$$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $$y = \\log_2 4 + 3$$\uc774 \ub418\uba70, $\\log_2 4 = 2$\uc774\ubbc0\ub85c $$y = 2 + 3 = 5$$\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c $x=5$\uc77c \ub54c\uc758 \ud568\uc22b\uac12\uc740 $5$\uc785\ub2c8\ub2e4."],ai0),v6,B.q)],ai2),v6,B.q)],ai3),s3,s3,s3,"concept_\ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504",0,"","\ub300\uc218 > \ub85c\uadf8\ud568\uc218 > \ub85c\uadf8\ud568\uc218\uc758\uadf8\ub798\ud504",c4,v6,s3)
